select * from customer_behavior;

-- alter database Customer_shopping_behavior modify name=customer_behavior;
-- What is the total revenue generated by male vs female customer

SELECT TABLE_SCHEMA, TABLE_NAME
FROM INFORMATION_SCHEMA.TABLES
WHERE TABLE_TYPE = 'BASE TABLE';

SELECT Gender,
       SUM(Purchase_Amount_USD) AS Revenue
FROM Customer_behavior
GROUP BY Gender;

-- which customer used a discount but still they spent more than the average purchase amount
select customer_id,Purchase_Amount_USD
from Customer_behavior
where Discount_Applied ='Yes' and Purchase_Amount_USD >= (select AVG(purchase_amount_usd) from customer_behavior);

-- which are the top 5 products with the highest average review ratings?
select top 5 item_purchased ,avg(review_rating)
from Customer_behavior
group by Item_Purchased
order by avg(review_rating) desc;

-- compare the average purchased amount between standard and express shipping.
select shipping_type,
round(avg(purchase_amount_usd),2)
from customer_behavior
where Shipping_Type in('Standard','Express')
group by Shipping_Type;

-- do subscribed customers spend more? compare average spend and total revenue between subcribers and non-subsccribers.
select subscription_status, count(customer_id) as total_customer,
round(avg(purchase_amount_usd),2) as avg_spend,
round(sum(purchase_amount_usd),2) as total_revenue
from customer_behavior
group by Subscription_Status
order by total_revenue,avg_spend desc;

-- which 5 products have the highest percentage of purchases with discounts applied?
SELECT TOP 5
    Item_Purchased,
    ROUND(
        SUM(CASE WHEN Discount_Applied = 'Yes' THEN 1 ELSE 0 END) * 100.0
        / COUNT(*), 2
    ) AS Discount_Rate
FROM Customer_Behavior
GROUP BY Item_Purchased
ORDER BY Discount_Rate DESC;

-- segment customers into new, returning and loyal based on their total number of previous purchases, and show the count of each segment.
WITH customer_type AS (
    SELECT
        Customer_ID,
        Previous_Purchases,
        CASE
            WHEN Previous_Purchases = 1 THEN 'New'
            WHEN Previous_Purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS Customer_Segment
    FROM Customer_Behavior
)

SELECT
    Customer_Segment,
    COUNT(*) AS Number_of_Customers
FROM customer_type
GROUP BY Customer_Segment;

-- what are the top 3 most purchased products within each category?
WITH item_counts AS (
    SELECT
        Category,
        Item_Purchased,
        COUNT(Customer_ID) AS Total_Orders,
        ROW_NUMBER() OVER (
            PARTITION BY Category
            ORDER BY COUNT(Customer_ID) DESC
        ) AS Item_Rank
    FROM Customer_Behavior
    GROUP BY Category, Item_Purchased
)

SELECT
    Item_Rank,
    Category,
    Item_Purchased,
    Total_Orders
FROM item_counts
WHERE Item_Rank <= 3
ORDER BY Category, Item_Rank;

-- are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from customer_behavior
where Previous_Purchases >5
group by Subscription_Status;

-- what is the revenue contribution of each age group?
SELECT
    Age,
    SUM(Purchase_Amount_usd) AS Total_Revenue
FROM Customer_Behavior
GROUP BY Age
ORDER BY Total_Revenue DESC;